# The mutations of Roxie.Line, sourced by scripts/in-gate.sh.
mutations+=(
	"Line.hiq|s/                    offset := 0 - offset;/                    offset := offset;/|an offset west counts as east"
	"Line.hiq|s/if (seconds >= 0) and (seconds <= now) then/if seconds >= 0 then/|a time after now is taken"
	"Line.hiq|s/if (seconds >= 0) and (seconds <= now) then/if seconds <= now then/|a time before 1970 is taken"
	"Line.hiq|s/case toInt64(m + 1) of/case toInt64(m) of/|the months are counted from 0"
	"Line.hiq|s/                        return \"warn\";/                        return \"info\";/|4xx is info"
	"Line.hiq|s/if text\[d + 31\] >= '5' then/if text[d + 31] > '5' then/|500 is not error"
	"Line.hiq|s/while (i < spanLength(text)) and (i <= addressMost) do/while i < spanLength(text) do/|a bar anywhere in the line"
	"Line.hiq|s/                if not isDigit(text\[at + i\]) then/                if false then/|any byte where a digit belongs"
	"Line.hiq|s/if (text\[d + 25\] \/= '+') and (text\[d + 25\] \/= '-') then/if false then/|no sign before the offset"
	"Line.hiq|s/                        return Some(value => stamp.instant.seconds);/                        return None();/|syslog is not read"
	"Line.hiq|s/hour => nat8Of(digitsAt(text, d + 16, 2)),/hour => nat8Of(digitsAt(text, d + 19, 2)),/|the minute read as the hour"
	"Line.hiq|s/year => int32Of(digitsAt(text, d + 11, 4)),/year => int32Of(digitsAt(text, d + 11, 3)),/|three digits of the year"
	"Line.hiq|s/if shapedAt(text, d + 31, \"999/if false and shapedAt(text, d + 31, \"999/|no status is read"
	#: the level of a JSON field.
	"Line.hiq|s/        if (wordAt(text, first, stop, \"info\") or/        if (false or/|INFO is not read"
	"Line.hiq|s/        if wordAt(text, first, stop, \"warn\") or wordAt(text, first, stop, \"warning\") then/        if wordAt(text, first, stop, \"warn\") then/|warning is not warn"
	"Line.hiq|s/                return levelOfWords(messageOf(text));/                return guessLevel(messageOf(text));/|no line looks for a field"
	"Line.hiq|s/            if (stop >= size) or (text\[stop\] \/= '\"') then/            if false then/|a level without its closing quote is read"
	#: logfmt, the priority, the message of syslog.
	"Line.hiq|s/ or wordAt(text, first, stop, \"audit\")//|AUDIT is not info"
	"Line.hiq|s/            if keyStart(text, at) and shapedAt(text, at, logfmt) then/            if false then/|logfmt is not read"
	"Line.hiq|s/        return text\[at - 1\] = ' ';/        return true;/|a key that ends in level= is read"
	"Line.hiq|s/                if (first < size) and (text\[first\] = '\"') then/                if false then/|a quoted value of logfmt keeps its quote"
	"Line.hiq|s/        if (size < 3) or (text\[0\] \/= '<') then/        if true then/|no priority is read"
	"Line.hiq|s/                if severity <= (3 : Int64) then/                if severity < (3 : Int64) then/|err is not error"
	"Line.hiq|s/                if severity = (4 : Int64) then/                if severity = (5 : Int64) then/|warning is not warn, notice is"
	"Line.hiq|s/        if digitsAt(text, 1, i - 1) > (191 : Int64) then/        if false then/|a priority above 191 is read"
	"Line.hiq|s/while ((i < size) and (i < 4)) and isDigit(text\[i\]) do/while (i < size) and isDigit(text[i]) do/|four digits make a priority"
	"Line.hiq|s/if ((i = 1) or (i >= size)) or (text\[i\] \/= '>') then/if (i >= size) or (text[i] \/= '>') then/|a priority without digits"
	"Line.hiq|s/            return Some(value => i + 3);/            return Some(value => i + 1);/|the version of RFC 5424 is not passed over"
	"Line.hiq|s/        if (i > program) and (text\[i - 1\] = ':') then/        if false then/|the name of the program is a word"
	"Line.hiq|s/        if i >= size then/        if false then/|a line without a host has no words"
	"Line.hiq|s/        if not isSyslog(text) then/        if false then/|every line is cut as syslog"
	#: the jobs of systemd.
	"Line.hiq|s/                if systemdJob(text) then/                if false then/|a job of systemd by its words"
	"Line.hiq|s/literalAt(text, program, \"systemd\[\")/literalAt(text, program, \"\")/|every program as systemd"
	"Line.hiq|s/literalAt(text, verb, \"Finished \")/literalAt(text, verb, \"Finished\")/|a verb without its space"
	"Line.hiq|s/                if text\[i - 1\] \/= ':' then/                if false then/|systemd without its colon"
	#: the BSD form.
	"Line.hiq|s/                return bsdTime(text, zone, now);/                return None();/|the BSD form is not read"
	"Line.hiq|s/                return bsdTime(substring(text, after, spanLength(text)), zone, now);/                return None();/|no BSD time after a priority"
	"Line.hiq|s/                        if (seconds - bsdAhead) <= now then/                        if true then/|a line of December is read in the year after"
	"Line.hiq|s/        return monthAt(text, 0) > 0;/        return true;/|no month name is needed"
	"Line.hiq|s/            day := digitsAt(text, 4, 2);/            day := digitsAt(text, 5, 1);/|a day of two digits read as one"
	"Line.hiq|s/            hour => nat8Of(digitsAt(text, 7, 2)),/            hour => nat8Of(digitsAt(text, 10, 2)),/|the minute of the BSD form read as the hour"
	"Line.hiq|s/        if (text\[4\] \/= ' ') and (not isDigit(text\[4\])) then/        if false then/|any byte before the day"
)
